var $bm_rt;
var speed = 12;
var amp = 9;
var freq = 0.2;
var lineWidth = 80;
var numPts = 40;
var centerX = 0;
var centerY = 0;
var t = $bm_mul(time, speed);
var pts = [];
for (var i = 0; i < numPts; i++) {
    var x = $bm_sum($bm_sub($bm_mul($bm_div(i, $bm_sub(numPts, 1)), lineWidth), $bm_div(lineWidth, 2)), centerX);
    var y = $bm_sum($bm_mul(Math.sin($bm_sum($bm_mul(i, freq), t)), amp), centerY);
    pts.push([
        x,
        y
    ]);
}
$bm_rt = createPath(pts, [], [], false);
